-macon-bibb-voters-pick-school-board-water-authority-seats/","published_on":"2026-05-20","fetched_on":"2026-10-21","publisher":"the-macon-melody","people":[{"slug":"steven-mcneel","role":"Mentioned"},{"slug":"greg-dolezal","role":"Mentioned"},{"slug":"casey-choung","role":"Author"}]},{"title":"Georgia legislators make 2nd effort to turn Ocmulgee Mounds into a national park, preserve","url":"https://www.macon.com/news/politics-government/article302841764.html","published_on":"2025-03-26","fetched_on":"2026-10-21","publisher":"the-macon-telegraph","people":[{"slug":"sanford-bishop","role":"Mentioned"},{"slug":"austin-scott","role":"Mentioned"},{"slug":"margaret-walker","role":"Author"}]},{"title":"I’m just a bill: The legislative process behind creating Georgia’s first national park","url":"https://maconmelody.com/im-just-a-bill-the-legislative-process-behind-creating-georgias-first-national-park/","published_on":"2024-06-25","fetched_on":"2026-10-21","publisher":"the-macon-melody","people":[{"slug":"austin-scott","role":"Mentioned"},{"slug":"caleb-slinkard","role":"Author"}]},{"title":"Ocmulgee Mounds National Park initiative gains momentum after Senate, House hearings","url":"https://maconmelody.com/ocmulgee-mounds-national-park-initiative-gains-momentum-after-senate-house-hearings/","published_on":"2024-11-20","fetched_on":"2026-10-21","publisher":"the-macon-melody","people":[{"slug":"austin-scott","role":"Mentioned"},{"slug":"sanford-bishop","role":"Mentioned"},{"slug":"evelyn-davidson","role":"Author"},{"slug":"caleb-slinkard","role":"Author"}]},{"title":"Republican candidate defends all-GOP Public Service Commission at Middle GA campaign stop","url":"https://www.macon.com/news/environment/article312614683.html","published_on":"2025-10-23","fetched_on":"2026-10-21","publisher":"the-macon-telegraph","people":[{"slug":"fitz-johnson","role":"Subject"},{"slug":"peter-hubbard","role":"Mentioned"},{"slug":"margaret-walker","role":"Author"}]},{"title":"Democratic governor candidate criticizes Kemp’s response to SNAP pause during Macon visit","url":"https://www.macon.com/news/politics-government/article312709840.html","published_on":"2025-10-30","fetched_on":"2026-10-21","publisher":"the-macon-telegraph","people":[{"slug":"keisha-lance-bottoms","role":"Mentioned"},{"slug":"lucinda-warnke","role":"Author"}]}]'::jsonb)
  loop
    select id into strict publisher_uuid from public.organizations where slug=item->>'publisher';
    insert into public.articles(title,url,visibility,published_on,fetched_on)
    values(item->>'title',item->>'url','public',(item->>'published_on')::date,(item->>'fetched_on')::date)
    on conflict(url) do nothing;
    select id into strict article_uuid from public.articles where url=item->>'url';
    update public.articles set published_on=coalesce(published_on,(item->>'published_on')::date),
      fetched_on=greatest(fetched_on,(item->>'fetched_on')::date) where id=article_uuid;
    for link in select value from jsonb_array_elements(item->'people')
    loop
      select id into strict person_uuid from public.people where slug=link->>'slug';
      insert into public.article_people(article_id,person_id,role)
      values(article_uuid,person_uuid,link->>'role') on conflict(article_id,person_id) do nothing;
    end loop;
    insert into public.article_organizations(article_id,organization_id,role)
    values(article_uuid,publisher_uuid,'Publisher') on conflict(article_id,organization_id) do nothing;
  end loop;
end;
